class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)

        def occurrences(seg):
            # start indices where seg occurs in s (KMP); an empty seg matches at 0..n
            m = len(seg)
            if m == 0:
                return list(range(n + 1))
            fail = [0] * m
            k = 0
            for i in range(1, m):
                while k and seg[i] != seg[k]:
                    k = fail[k - 1]
                if seg[i] == seg[k]:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i, ch in enumerate(s):
                while k and (k == m or ch != seg[k]):
                    k = fail[k - 1]
                if ch == seg[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
            return res

        INF = float('inf')

        # bestA[j] = largest start of an occurrence of A that ends at or before j (else -1)
        bestA = [-1] * (n + 2)
        for a in occurrences(A):
            e = a + len(A)
            if a > bestA[e]:
                bestA[e] = a
        for j in range(1, n + 2):
            if bestA[j - 1] > bestA[j]:
                bestA[j] = bestA[j - 1]

        # nextC[j] = smallest start of an occurrence of C that is >= j (else INF)
        nextC = [INF] * (n + 2)
        for c in occurrences(C):
            nextC[c] = c
        for j in range(n, -1, -1):
            if nextC[j + 1] < nextC[j]:
                nextC[j] = nextC[j + 1]

        ans = INF
        for b in occurrences(B):
            a = bestA[b]
            c = nextC[b + len(B)]
            if a != -1 and c != INF:
                ans = min(ans, c + len(C) - a)
        return -1 if ans == INF else ans
